declare_lint ! { #[doc = " The `edition_2024_expr_fragment_specifier` lint detects the use of"] #[doc = " `expr` fragments in macros during migration to the 2024 edition."] #[doc = ""] #[doc = " The `expr` fragment specifier will accept more expressions in the 2024"] #[doc = " edition. To maintain the behavior from the 2021 edition and earlier, use"] #[doc = " the `expr_2021` fragment specifier."] #[doc = ""] #[doc = " ### Example"] #[doc = ""] #[doc = " ```rust,edition2021,compile_fail"] #[doc = " #![deny(edition_2024_expr_fragment_specifier)]"] #[doc = " macro_rules! m {"] #[doc = "   ($e:expr) => {"] #[doc = "       $e"] #[doc = "   }"] #[doc = " }"] #[doc = ""] #[doc = " fn main() {"] #[doc = "    m!(1);"] #[doc = " }"] #[doc = " ```"] #[doc = ""] #[doc = " {{produces}}"] #[doc = ""] #[doc = " ### Explanation"] #[doc = ""] #[doc = " Rust [editions] allow the language to evolve without breaking backwards"] #[doc = " compatibility. This lint catches code that uses [macro matcher fragment"] #[doc = " specifiers] that have changed meaning in the 2024 edition. If you switch"] #[doc = " to the new edition without updating the code, your macros may behave"] #[doc = " differently."] #[doc = ""] #[doc = " In the 2024 edition, the `expr` fragment specifier `expr` will also"] #[doc = " match `const { ... }` blocks. This means if a macro had a pattern that"] #[doc = " matched `$e:expr` and another that matches `const { $e: expr }`, for"] #[doc = " example, that under the 2024 edition the first pattern would match while"] #[doc = " in the 2021 and earlier editions the second pattern would match. To keep"] #[doc = " the old behavior, use the `expr_2021` fragment specifier."] #[doc = ""] #[doc = " This lint detects macros whose behavior might change due to the changing"] #[doc = " meaning of the `expr` fragment specifier. It is \"allow\" by default"] #[doc = " because the code is perfectly valid in older editions. The [`cargo fix`]"] #[doc = " tool with the `--edition` flag will switch this lint to \"warn\" and"] #[doc = " automatically apply the suggested fix from the compiler. This provides a"] #[doc = " completely automated way to update old code for a new edition."] #[doc = ""] #[doc = " Using `cargo fix --edition` with this lint will ensure that your code"] #[doc = " retains the same behavior. This may not be the desired, as macro authors"] #[doc = " often will want their macros to use the latest grammar for matching"] #[doc = " expressions. Be sure to carefully review changes introduced by this lint"] #[doc = " to ensure the macros implement the desired behavior."] #[doc = ""] #[doc = " [editions]: https://doc.rust-lang.org/edition-guide/"] #[doc = " [macro matcher fragment specifiers]: https://doc.rust-lang.org/edition-guide/rust-2024/macro-fragment-specifiers.html"] #[doc = " [`cargo fix`]: https://doc.rust-lang.org/cargo/commands/cargo-fix.html"] pub EDITION_2024_EXPR_FRAGMENT_SPECIFIER , Allow , "The `expr` fragment specifier will accept more expressions in the 2024 edition. \
    To keep the existing behavior, use the `expr_2021` fragment specifier." , @ future_incompatible = FutureIncompatibleInfo { reason : FutureIncompatibilityReason :: EditionSemanticsChange (Edition :: Edition2024) , reference : "Migration Guide <https://doc.rust-lang.org/edition-guide/rust-2024/macro-fragment-specifiers.html>" ,}
; }